import 'package:cloud_firestore/cloud_firestore.dart';
import '../../core/models/talent.dart';
class TalentRepository{final FirebaseFirestore db;TalentRepository({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance;
Stream<List<AurenTalent>> watchPublic({String query='',String skill=''}){final q=query.trim().toLowerCase(),s=skill.trim().toLowerCase();return db.collection('talents').where('status',isEqualTo:'active').limit(100).snapshots().map((snap){final list=snap.docs.map((d)=>AurenTalent.fromMap(d.id,d.data())).where((t)=>q.isEmpty||('${t.displayName} ${t.bio} ${t.category} ${t.city} ${t.country} ${t.skills.join(' ')}').toLowerCase().contains(q)).where((t)=>s.isEmpty||t.skills.any((x)=>x.toLowerCase()==s)).toList();list.sort((a,b)=>a.displayName.toLowerCase().compareTo(b.displayName.toLowerCase()));return list;});}
Future<String> save({required String ownerId,required String displayName,required String bio,required String category,required String city,required String country,required List<String> skills})async{final ref=db.collection('talents').doc();await ref.set({'ownerId':ownerId,'displayName':displayName.trim(),'bio':bio.trim(),'category':category.trim(),'city':city.trim(),'country':country.trim(),'skills':skills.map((e)=>e.trim().toLowerCase()).where((e)=>e.isNotEmpty).take(30).toList(),'status':'active','updatedAt':FieldValue.serverTimestamp()});return ref.id;}}